from copy import deepcopy

from dateutil.parser import parse as convert_to_datetime


def time(time_string):
    """
    :param string time_string:
    :rtype: datetime.time
    """
    return convert_to_datetime(time_string).time()


def date(date_string):
    """
    :param string date_string:
    :rtype: datetime.date
    """
    return convert_to_datetime(date_string).date()


def convert_report(report):
    """
    Converts values in report to corresponding types.

    :param dict report:
    :return: parsed report
    :rtype: dict
    """
    report_converters = {
        'creationTime': convert_to_datetime,
        'monitoredIntervalStart': date,
        'monitoredIntervalEnd': date,
    }
    return _convert(report, report_converters)


def convert_module(module):
    """
    Converts values in module to corresponding types.

    :param dict module:
    :return: parsed module
    :rtype: dict
    """
    module_converters = {
        'dailyReportGenerationTime': time
    }
    return _convert(module, module_converters)


def _convert(item, converter):
    item = deepcopy(item)
    for param, converting_function in converter.items():
        if param in item:
            item[param] = converting_function(item[param])
    return item
